3251:     /// ```
3252:     /// use std::collections::VecDeque;
3253:     ///
3254:     /// let deque: VecDeque<_> = [1, 2, 3, 3, 5, 6, 7].into();
3255:     /// let i = deque.partition_point(|&x| x < 5);
3256:     ///
3257:     /// assert_eq!(i, 4);
3258:     /// assert!(deque.iter().take(i).all(|&x| x < 5));
3259:     /// assert!(deque.iter().skip(i).all(|&x| !(x < 5)));
3260:     /// ```
